package ai.nexora.videomanager

import android.content.ContentValues
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.os.SystemClock
import android.provider.MediaStore
import android.view.View
import android.widget.ArrayAdapter
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import ai.nexora.videomanager.databinding.ActivityMainBinding
import org.json.JSONObject
import java.io.DataOutputStream
import java.net.HttpURLConnection
import java.net.URL

class MainActivity : AppCompatActivity() {
 private lateinit var b:ActivityMainBinding; private var mediaUri:Uri?=null
 private var segments=mutableListOf<Seg>(); private var voices=mutableListOf<Voice>(); private val speakerVoice=mutableMapOf<String,String>()
 private val handler=Handler(Looper.getMainLooper()); private var started=0L; private var timer:Runnable?=null
 data class Seg(val speaker:String,val start:Double,val end:Double,var text:String); data class Voice(val id:String,val name:String)
 private val picker=registerForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null){mediaUri=uri;try{contentResolver.takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION)}catch(_:Exception){};b.fileText.text="បានជ្រើស៖ ${uri.lastPathSegment?:"media"}";toast("បានជ្រើស Video/Audio រួចរាល់")}}
 private val srtPicker=registerForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null){try{val txt=contentResolver.openInputStream(uri)?.bufferedReader()?.readText().orEmpty();b.scriptText.setText(txt);status("✅ Import SRT រួចរាល់") }catch(e:Exception){status("❌ ${e.message}")}}}
 override fun onCreate(s:Bundle?){super.onCreate(s);b=ActivityMainBinding.inflate(layoutInflater);setContentView(b.root)
  ArrayAdapter.createFromResource(this,R.array.tts_models,android.R.layout.simple_spinner_item).also{it.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);b.modelSpinner.adapter=it}
  val gm=arrayOf("gemini-2.5-pro (Recommended)","gemini-2.5-flash","gemini-2.5-flash-lite");b.geminiModelSpinner.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,gm)
  b.pickButton.setOnClickListener{picker.launch(arrayOf("video/*","audio/*"))};b.srtButton.setOnClickListener{srtPicker.launch(arrayOf("application/x-subrip","text/plain","*/*"))};b.transcribeButton.setOnClickListener{runTranscribe()};b.voicesButton.setOnClickListener{loadVoicesAndAssign()};b.translateButton.setOnClickListener{translateKhmer()};b.voiceAllButton.setOnClickListener{generateAll()};b.outputButton.setOnClickListener{toast("Output: Music/MovieScriptDubAI")};b.exportButton.setOnClickListener{exportSrt()}}
 private fun begin(title:String,hint:String){started=SystemClock.elapsedRealtime();b.progressPanel.visibility=View.VISIBLE;b.progressTitle.text=title;b.progressHint.text=hint;b.progressBar.progress=1;b.progressPercent.text="1%";timer?.let{handler.removeCallbacks(it)};timer=object:Runnable{override fun run(){val sec=(SystemClock.elapsedRealtime()-started)/1000;b.progressTime.text=String.format("%02d:%02d",sec/60,sec%60);handler.postDelayed(this,1000)}};handler.post(timer!!)}
 private fun prog(p:Int,h:String){runOnUiThread{val x=p.coerceIn(0,100);b.progressBar.progress=x;b.progressPercent.text="$x%";b.progressHint.text=h}}
 private fun done(msg:String){prog(100,msg);timer?.let{handler.removeCallbacks(it)}}
 private fun runTranscribe(){val key=b.elevenKey.text.toString().trim();val uri=mediaUri;if(key.isBlank()||uri==null){status("⚠️ សូមដាក់ ElevenLabs API Key និងជ្រើសវីដេអូ/អូឌីយ៉ូជាមុន។");return};b.transcribeButton.isEnabled=false;begin("Auto Script + ចាប់តួអង្គ","1. Uploading video… 0%\n2. Speech Recognition (STT)…\n3. Detecting Speakers…\n4. Generating Script…");status("⏳ កំពុងដំណើរការ…");Thread{try{prog(8,"1. Connecting ElevenLabs… 8%\n2. Speech Recognition (STT)…\n3. Detecting Speakers…\n4. Generating Script…");val boundary="----MovieScript${System.currentTimeMillis()}";val mime=contentResolver.getType(uri)?:"application/octet-stream";val c=(URL("https://api.elevenlabs.io/v1/speech-to-text").openConnection() as HttpURLConnection).apply{requestMethod="POST";doOutput=true;connectTimeout=30000;readTimeout=300000;setRequestProperty("xi-api-key",key);setRequestProperty("Accept","application/json");setRequestProperty("Content-Type","multipart/form-data; boundary=$boundary")};DataOutputStream(c.outputStream).use{out->fun field(n:String,v:String){out.writeBytes("--$boundary\r\nContent-Disposition: form-data; name=\"$n\"\r\n\r\n$v\r\n")};field("model_id","scribe_v2");field("diarize","true");field("timestamps_granularity","word");out.writeBytes("--$boundary\r\nContent-Disposition: form-data; name=\"file\"; filename=\"media\"\r\nContent-Type: $mime\r\n\r\n");contentResolver.openInputStream(uri)?.use{input->val total=try{contentResolver.openAssetFileDescriptor(uri,"r")?.length?:-1}catch(_:Exception){-1};val buf=ByteArray(256*1024);var read:Int;var sent=0L;while(input.read(buf).also{read=it}>0){out.write(buf,0,read);sent+=read;if(total>0){val up=(sent*100/total).toInt().coerceAtMost(100);val p=(10+(sent*40/total)).toInt().coerceAtMost(50);prog(p,"✓ 1. Uploading video… $up%\n2. Speech Recognition (STT)…\n3. Detecting Speakers…\n4. Generating Script…")}}}?:throw Exception("មិនអាចអាន file បាន");out.writeBytes("\r\n--$boundary--\r\n");out.flush()};prog(60,"✓ 1. Uploading video… 100%\n⏳ 2. Speech Recognition (STT)…\n⏳ 3. Detecting Speakers…\n4. Generating Script…");val code=c.responseCode;val raw=(if(code in 200..299)c.inputStream else c.errorStream)?.bufferedReader()?.readText().orEmpty();if(code !in 200..299)throw Exception("ElevenLabs HTTP $code: ${raw.take(350)}");prog(88,"✓ 1. Uploading video… 100%\n✓ 2. Speech Recognition (STT)… 100%\n✓ 3. Detecting Speakers… 100%\n⏳ 4. Generating Script… 88%");val words=JSONObject(raw).optJSONArray("words");val result=mutableListOf<Seg>();var cur:Seg?=null;if(words!=null)for(i in 0 until words.length()){val w=words.getJSONObject(i);if(w.optString("type")!="word")continue;val sp=w.optString("speaker_id","speaker_0").ifBlank{"speaker_0"};val st=w.optDouble("start",0.0);val en=w.optDouble("end",st);val tx=w.optString("text");if(cur==null||cur!!.speaker!=sp||st-cur!!.end>1.2){if(cur!=null)result.add(cur!!);cur=Seg(sp,st,en,tx)}else cur=cur!!.copy(end=en,text=(cur!!.text+" "+tx).trim())};if(cur!=null)result.add(cur!!);segments=result;runOnUiThread{renderScript();done("✓ Upload 100% • ✓ STT 100% • ✓ Speakers 100% • ✓ Script 100%");status("✅ Script រួចរាល់ • ${segments.size} segments • ${segments.map{it.speaker}.distinct().size} តួអង្គ");b.transcribeButton.isEnabled=true}}catch(e:Exception){runOnUiThread{timer?.let{handler.removeCallbacks(it)};status("❌ ${e.message}");b.progressHint.text="មានបញ្ហា — សូមមើលសារខាងក្រោម";b.transcribeButton.isEnabled=true}}}.start()}
 private fun loadVoicesAndAssign(){val key=b.elevenKey.text.toString().trim();if(key.isBlank()){status("⚠️ សូមដាក់ ElevenLabs API Key ជាមុន។");return};begin("Load Voices + Auto Assign","កំពុងទាញបញ្ជីសម្លេង…");b.voicesButton.isEnabled=false;Thread{try{prog(30,"កំពុងភ្ជាប់ ElevenLabs Voices…");val c=(URL("https://api.elevenlabs.io/v2/voices?page_size=100").openConnection() as HttpURLConnection).apply{connectTimeout=30000;readTimeout=60000;setRequestProperty("xi-api-key",key)};val code=c.responseCode;val raw=(if(code in 200..299)c.inputStream else c.errorStream)?.bufferedReader()?.readText().orEmpty();if(code !in 200..299)throw Exception("HTTP $code: ${raw.take(300)}");prog(75,"កំពុង Auto Assign តាមតួអង្គ…");val a=JSONObject(raw).getJSONArray("voices");voices=MutableList(a.length()){i->val v=a.getJSONObject(i);Voice(v.getString("voice_id"),v.getString("name"))};val ss=segments.map{it.speaker}.distinct();speakerVoice.clear();ss.forEachIndexed{i,x->if(voices.isNotEmpty())speakerVoice[x]=voices[i%voices.size].id};runOnUiThread{b.mappingText.text=if(ss.isEmpty())"⚠️ Auto Script ជាមុន" else ss.joinToString("\n"){x->"$x → ${voices.find{it.id==speakerVoice[x]}?.name?:"-"}"};done("Auto Assign រួចរាល់");status("✅ Load ${voices.size} voices");b.voicesButton.isEnabled=true}}catch(e:Exception){runOnUiThread{timer?.let{handler.removeCallbacks(it)};status("❌ ${e.message}");b.voicesButton.isEnabled=true}}}.start()}
 private fun translateKhmer(){val key=b.geminiKey.text.toString().trim();if(key.isBlank()||segments.isEmpty()){status("⚠️ ត្រូវមាន Gemini API Key និង Script ជាមុន។");return};begin("បកប្រែ Script → Khmer","កំពុងផ្ញើ Script ទៅ Gemini…");b.translateButton.isEnabled=false;Thread{try{prog(25,"កំពុងបកប្រែ…");val model=when(b.geminiModelSpinner.selectedItemPosition){1->"gemini-2.5-flash";2->"gemini-2.5-flash-lite";else->"gemini-2.5-pro"};val prompt="Translate each line to natural Khmer dubbing. Keep speaker labels and timestamps. Return plain lines only.\n"+segments.joinToString("\n"){"${it.speaker}|${it.start}|${it.end}|${it.text}"};val body=JSONObject().put("contents",org.json.JSONArray().put(JSONObject().put("parts",org.json.JSONArray().put(JSONObject().put("text",prompt))))).toString();val c=(URL("https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$key").openConnection() as HttpURLConnection).apply{requestMethod="POST";doOutput=true;connectTimeout=30000;readTimeout=120000;setRequestProperty("Content-Type","application/json")};c.outputStream.use{it.write(body.toByteArray())};prog(60,"Gemini កំពុងបកប្រែ…");val code=c.responseCode;val raw=(if(code in 200..299)c.inputStream else c.errorStream)?.bufferedReader()?.readText().orEmpty();if(code !in 200..299)throw Exception("Gemini HTTP $code: ${raw.take(300)}");val out=JSONObject(raw).getJSONArray("candidates").getJSONObject(0).getJSONObject("content").getJSONArray("parts").getJSONObject(0).getString("text");val lines=out.lines().filter{it.contains("|")};lines.take(segments.size).forEachIndexed{i,l->segments[i].text=l.substringAfterLast("|").trim()};runOnUiThread{renderScript();done("បកប្រែរួចរាល់");status("✅ បកប្រែខ្មែររួចរាល់");b.translateButton.isEnabled=true}}catch(e:Exception){runOnUiThread{timer?.let{handler.removeCallbacks(it)};status("❌ ${e.message}");b.translateButton.isEnabled=true}}}.start()}
 private fun generateAll(){val key=b.elevenKey.text.toString().trim();if(key.isBlank()||segments.isEmpty()||speakerVoice.isEmpty()){status("⚠️ ត្រូវមាន Script និង Auto Assign Voice ជាមុន។");return};val model=when(b.modelSpinner.selectedItemPosition){1->"eleven_flash_v2_5";2->"eleven_turbo_v2_5";else->"eleven_multilingual_v2"};begin("Voice All — Generate ទាំងអស់","កំពុងរៀបចំសម្លេង…");b.voiceAllButton.isEnabled=false;Thread{try{segments.forEachIndexed{i,s->val p=((i.toDouble()/segments.size)*95).toInt().coerceAtLeast(2);prog(p,"Generating voices… ${i+1}/${segments.size}\n${s.speaker}");val vid=speakerVoice[s.speaker]?:return@forEachIndexed;val body=JSONObject().put("text",s.text).put("model_id",model).toString();val c=(URL("https://api.elevenlabs.io/v1/text-to-speech/$vid?output_format=mp3_44100_128").openConnection() as HttpURLConnection).apply{requestMethod="POST";doOutput=true;connectTimeout=30000;readTimeout=120000;setRequestProperty("xi-api-key",key);setRequestProperty("Content-Type","application/json")};c.outputStream.use{it.write(body.toByteArray())};val code=c.responseCode;if(code !in 200..299)throw Exception("TTS HTTP $code: ${c.errorStream?.bufferedReader()?.readText().orEmpty().take(250)}");saveMp3("segment_${String.format("%04d",i+1)}_${s.speaker}.mp3",c.inputStream.readBytes())};runOnUiThread{done("Voice All រួចរាល់");status("✅ MP3 រក្សាទុកក្នុង Music/MovieScriptDubAI");b.voiceAllButton.isEnabled=true}}catch(e:Exception){runOnUiThread{timer?.let{handler.removeCallbacks(it)};status("❌ ${e.message}");b.voiceAllButton.isEnabled=true}}}.start()}
 private fun saveMp3(n:String,x:ByteArray){val v=ContentValues().apply{put(MediaStore.Audio.Media.DISPLAY_NAME,n);put(MediaStore.Audio.Media.MIME_TYPE,"audio/mpeg");put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/MovieScriptDubAI")};contentResolver.insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,v)?.let{u->contentResolver.openOutputStream(u)?.use{it.write(x)}}}
 private fun exportSrt(){if(segments.isEmpty()){status("⚠️ មិនទាន់មាន Script សម្រាប់ Export");return};val text=segments.mapIndexed{i,s->"${i+1}\n${srt(s.start)} --> ${srt(s.end)}\n${s.speaker}: ${s.text}\n"}.joinToString("\n");val v=ContentValues().apply{put(MediaStore.Downloads.DISPLAY_NAME,"MovieScript_Dub_AI.srt");put(MediaStore.Downloads.MIME_TYPE,"application/x-subrip");put(MediaStore.Downloads.RELATIVE_PATH,"Download/MovieScriptDubAI")};contentResolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v)?.let{u->contentResolver.openOutputStream(u)?.use{it.write(text.toByteArray())}};status("✅ Export SRT → Download/MovieScriptDubAI")}
 private fun renderScript(){b.scriptText.setText(segments.joinToString("\n"){"[${time(it.start)}] ${it.speaker}: ${it.text}"})};private fun time(v:Double):String{val t=v.toInt();return String.format("%02d:%02d:%02d",t/3600,(t%3600)/60,t%60)};private fun srt(v:Double):String{val t=v.toInt();val ms=((v-t)*1000).toInt();return String.format("%02d:%02d:%02d,%03d",t/3600,(t%3600)/60,t%60,ms)};private fun status(s:String){b.statusText.text=s};private fun toast(s:String){Toast.makeText(this,s,Toast.LENGTH_SHORT).show()}
}